import json
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def run_cmd(host, dtype, user, pwd, cmds):
    results = {}
    try:
        conn = ConnectHandler(host=host, device_type=dtype, username=user, password=pwd)
        for cmd in cmds:
            try:
                results[cmd] = conn.send_command(cmd, read_timeout=30)
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["CONNECTION_ERROR"] = str(e)
    return results

def main():
    results = {}

    with ThreadPoolExecutor(max_workers=19) as pool:
        futures = {}

        # HQ-Edge
        futures["HQ-Edge"] = pool.submit(run_cmd, "192.168.122.11", "vyos", "vyos", "test", [
            "show ip ospf neighbor",
            "show ip bgp summary",
            "show ip bgp",
            "show ip bgp neighbors 203.0.113.1 advertised-routes",
            "show ip bgp neighbors 203.0.113.5 advertised-routes",
            "show ip route",
        ])
        # Hub-A
        futures["Hub-A"] = pool.submit(run_cmd, "192.168.122.12", "vyos", "vyos", "test", [
            "show ip ospf neighbor",
            "show ip route",
        ])
        # Hub-B
        futures["Hub-B"] = pool.submit(run_cmd, "192.168.122.13", "vyos", "vyos", "test", [
            "show ip ospf neighbor",
            "show ip route",
        ])
        # Branches
        for i, br in enumerate(["Branch-1", "Branch-2", "Branch-3", "Branch-4"], 1):
            ip = f"192.168.122.2{i}"
            futures[br] = pool.submit(run_cmd, ip, "mikrotik_routeros", "admin", "test", [
                "/routing ospf neighbor print detail",
                "/ip route print terse",
            ])

        for name, f in futures.items():
            results[name] = f.result()

    # Print results
    for name in ["HQ-Edge", "Hub-A", "Hub-B", "Branch-1", "Branch-2", "Branch-3", "Branch-4"]:
        print(f"\n{'='*60}")
        print(f"=== {name} ===")
        for cmd, out in results[name].items():
            print(f"--- {cmd} ---")
            print(out)

if __name__ == "__main__":
    main()

